	@Test
	void queryRootCaptureKeepsSuppliedGraphForAnEqualCopiedValue() {
		ValueFactory vf = SimpleValueFactory.getInstance();
		IRI graph = vf.createIRI("urn:root-capture:graph");
		IRI otherGraph = vf.createIRI("urn:root-capture:other");
		AtomicInteger captures = new AtomicInteger();
		DefaultEvaluationStrategy strategy = rootCaptureStrategy(value -> {
			if (value instanceof IRI iri) {
				captures.incrementAndGet();
				return vf.createIRI(iri.stringValue());
			}
			return value;
		});
		MutableBindingSet supplied = GraphFrameBindings.supply(new QueryBindingSet(), "g", graph);
		supplied = GraphFrameBindings.supply(supplied, "h", otherGraph);
		BindingSet direct = single(strategy.precompile(new SingletonSet(), CONTEXT), supplied);
		assertThat(GraphFrameBindings.isSupplied(direct, "g")).isTrue();
		assertThat(GraphFrameBindings.isSupplied(direct, "h")).isTrue();
		assertThat(captures).hasValue(0);

		QueryEvaluationStep hosted = strategy.precompile(new QueryRoot(new SingletonSet()), CONTEXT);
		BindingSet result = single(hosted, supplied);
		assertThat(captures.get()).isGreaterThanOrEqualTo(2);
		assertThat(result.getValue("g")).isEqualTo(graph).isNotSameAs(graph);
		assertThat(result.getValue("h")).isEqualTo(otherGraph).isNotSameAs(otherGraph);
		assertThat(GraphFrameBindings.isSupplied(result, "g"))
				.as("semantic capture is not a local GRAPH binding write")
				.isTrue();
		assertThat(GraphFrameBindings.isSupplied(result, "h")).isTrue();
	}

	@Test
	void queryRootCaptureDoesNotCreateGraphAuthorityAndLocalWritesRevokeIt() {
		ValueFactory vf = SimpleValueFactory.getInstance();
		IRI graph = vf.createIRI("urn:root-capture:graph");
		IRI otherGraph = vf.createIRI("urn:root-capture:other");
		DefaultEvaluationStrategy copying = rootCaptureStrategy(value -> value instanceof IRI iri
				? vf.createIRI(iri.stringValue())
				: value);
		DefaultEvaluationStrategy unchanged = rootCaptureStrategy(Function.identity());
		List<QueryEvaluationStep> steps = List.of(copying.precompile(new SingletonSet(), CONTEXT),
				unchanged.precompile(new QueryRoot(new SingletonSet()), CONTEXT),
				copying.precompile(new QueryRoot(new SingletonSet()), CONTEXT));
		for (QueryEvaluationStep step : steps) {
			BindingSet plain = single(step, row("g", graph));
			assertThat(plain.getValue("g")).isEqualTo(graph);
			assertThat(GraphFrameBindings.isSupplied(plain, "g")).isFalse();

			BindingSet probe = BindingFrameBindings.push(new BindingFrameBindings.Scope(), row("unrelated", graph),
					row("g", graph), CONTEXT);
			assertThat(probe.getValue("g")).isNull();
			BindingSet probed = single(step, probe);
			assertThat(probed.getValue("g")).isNull();
			assertThat(BindingFrameBindings.probeValue(probed, "g")).isEqualTo(graph);
			assertThat(GraphFrameBindings.isSupplied(probed, "g")).isFalse();

			MutableBindingSet supplied = GraphFrameBindings.supply(new QueryBindingSet(), "g", graph);
			supplied = GraphFrameBindings.supply(supplied, "h", otherGraph);
			QueryBindingSet result = new QueryBindingSet(single(step, supplied));
			assertThat(GraphFrameBindings.isSupplied(result, "g")).isTrue();
			assertThat(GraphFrameBindings.isSupplied(result, "h")).isTrue();
			QueryBindingSet equalWrite = new QueryBindingSet(result);
			IRI equalGraph = vf.createIRI(graph.stringValue());
			assertThat(equalGraph).isEqualTo(graph).isNotSameAs(graph);
			equalWrite.setBinding("g", equalGraph);
			assertThat(equalWrite.getValue("g")).isEqualTo(graph);
			assertThat(GraphFrameBindings.isSupplied(equalWrite, "g"))
					.as("a local equal-valued write revokes the original grant")
					.isFalse();
			assertThat(GraphFrameBindings.isSupplied(equalWrite, "h")).isTrue();
			result.setBinding("g", otherGraph);
			assertThat(GraphFrameBindings.isSupplied(result, "g")).isFalse();
			assertThat(GraphFrameBindings.isSupplied(result, "h")).isTrue();
			result.removeBinding("h");
			assertThat(GraphFrameBindings.isSupplied(result, "h")).isFalse();
		}
	}

	private static DefaultEvaluationStrategy rootCaptureStrategy(Function<Value, Value> capturer) {
		return new DefaultEvaluationStrategy(new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				throw new AssertionError("the singleton source performs no statement lookup");
			}

			@Override
			public ValueFactory getValueFactory() {
				return SimpleValueFactory.getInstance();
			}

			@Override
			public Function<Value, Value> getValueCapturer() {
				return capturer;
			}
		}, null);
	}

	private static BindingSet single(QueryEvaluationStep step, BindingSet input) {
		try (var rows = step.evaluate(input)) {
			assertThat(rows.hasNext()).isTrue();
			BindingSet result = rows.next();
			assertThat(rows.hasNext()).isFalse();
			return result;
		}
	}

	@Test
	void scopedStatementLookupKeepsSuppliedGraphProvenance() {
		ValueFactory vf = SimpleValueFactory.getInstance();
		IRI subject = vf.createIRI("urn:lookup:subject");
		IRI predicate = vf.createIRI("urn:lookup:predicate");
		IRI object = vf.createIRI("urn:lookup:object");
		IRI graph = vf.createIRI("urn:lookup:graph");
		Statement statement = vf.createStatement(subject, predicate, object, graph);
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource actualSubject, IRI actualPredicate,
					Value actualObject, Resource... contexts) {
				assertThat(actualSubject).isEqualTo(subject);
				assertThat(contexts).containsExactly(graph);
				return new CloseableIteratorIteration<>(List.of(statement).iterator());
			}

			@Override
			public ValueFactory getValueFactory() {
				return vf;
			}
		};
		StatementPattern pattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("b"),
				Var.of("p", predicate, false, true), Var.of("o"), Var.of("g"));
		var step = new StatementPatternQueryEvaluationStep(pattern, CONTEXT, source);
		BindingFrameBindings.Scope owner = new BindingFrameBindings.Scope();
		try (BindingFrameReplay.Invocation invocation = new BindingFrameReplay.Invocation(DefaultCollectionFactory::new,
				null)) {
			invocation.root.registerLookupInputs(owner, "b"::equals);
			MutableBindingSet entry = GraphFrameBindings.supply(new QueryBindingSet(), "g", graph);
			BindingSet input = BindingFrameBindings.push(owner, entry, row("b", subject), CONTEXT, invocation.root);
			try (var rows = step.evaluate(input)) {
				assertThat(rows.hasNext()).isTrue();
				BindingSet result = rows.next();
				assertThat(result.getValue("b")).isEqualTo(subject);
				assertThat(result.getValue("o")).isEqualTo(object);
				assertThat(result.getValue("g")).isEqualTo(graph);
				assertThat(GraphFrameBindings.isSupplied(result, "g")).isTrue();
				assertThat(BindingFrameBindings.probeValue(result, "b")).isEqualTo(subject);
				assertThat(rows.hasNext()).isFalse();
			}
		}
	}

	@Test
	void replayLookupBarrierPreservesOwnerInputsAcrossSerialization() throws Exception {
		BindingFrameBindings.Scope outer = new BindingFrameBindings.Scope();
		BindingFrameBindings.Scope inner = new BindingFrameBindings.Scope();
		try (BindingFrameReplay.Invocation invocation = new BindingFrameReplay.Invocation(DefaultCollectionFactory::new,
				null)) {
			invocation.root.registerLookupInputs(outer, "outer"::equals);
			invocation.root.registerLookupInputs(inner, "inner"::equals);
			BindingSet outerFrame = BindingFrameBindings.push(outer, EmptyBindingSet.getInstance(), row("outer", VALUE),
					CONTEXT, invocation.root);
			BindingSet barrier = BindingFrameBindings.isolateLookupProbes(outerFrame, CONTEXT);
			assertThat(BindingFrameBindings.probeValue(barrier, "outer")).isEqualTo(VALUE);
			assertThat(BindingFrameBindings.from(barrier).lookupProbe("outer")).isNull();
			BindingSet nested = BindingFrameBindings.push(inner, barrier, row("inner", LOCAL), CONTEXT,
					invocation.root);
			assertThat(BindingFrameBindings.from(nested).lookupProbe("inner")).isEqualTo(LOCAL);
			assertThat(BindingFrameBindings.from(nested).lookupProbe("outer")).isNull();
			ByteArrayOutputStream bytes = new ByteArrayOutputStream();
			try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
				output.writeObject(nested);
			}
			try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
				BindingSet deserialized = (BindingSet) input.readObject();
				BindingFrame restored = BindingFrameBindings.restoreFrame(BindingFrameBindings.from(deserialized),
						BindingFrameBindings.from(nested));
				assertThat(restored.lookupProbe("inner")).isEqualTo(LOCAL);
				assertThat(restored.lookupProbe("outer")).isNull();
				assertThat(restored.probe("outer")).isEqualTo(VALUE);
			}
		}
	}

	@Test
	void scopeIdentityBelongsToTheOriginalOwnerRatherThanCopiedMetadata() {
		Join owner = new Join(new SingletonSet(), new SingletonSet());
		BindingFrameBindings.Scope scope = BindingFrameBindings.scopeFor(owner);
		assertThat(BindingFrameBindings.scopeFor(owner)).isSameAs(scope);
		Join clone = owner.clone();
		BindingFrameBindings.Scope clonedScope = BindingFrameBindings.scopeFor(clone);
		assertThat(clonedScope).isNotEqualTo(scope);
		assertThat(BindingFrameBindings.scopeFor(clone)).isSameAs(clonedScope);
		assertThat(BindingFrameBindings.scopeFor(owner)).isSameAs(scope);
	}

	@Test
	void seedSnapshotIsInvisibleAndSurvivesBothBindingRepresentations() {
		QueryBindingSet seeds = row("seed", VALUE);
		BindingSet framed = BindingFrameBindings.push(new BindingFrameBindings.Scope(),
				EmptyBindingSet.getInstance(), seeds, CONTEXT);
		seeds.setBinding("seed", LOCAL);
		assertThat(framed).isEmpty();
		assertThat(framed).isEqualTo(EmptyBindingSet.getInstance());
		assertThat(framed.hashCode()).isEqualTo(EmptyBindingSet.getInstance().hashCode());
		assertThat(framed.getBindingNames()).isEmpty();
		assertThat(framed.getValue("seed")).isNull();
		QueryBindingSet queryCopy = new QueryBindingSet(framed);
		String[] names = { "seed", "local" };
		ArrayBindingSet arrayCopy = new ArrayBindingSet(queryCopy, Set.of(names), names);
		assertThat(BindingFrameBindings.materialize(arrayCopy, Set.of("seed")).getValue("seed")).isEqualTo(VALUE);
		arrayCopy.setBinding("seed", LOCAL);
		assertThat(BindingFrameBindings.materialize(arrayCopy, Set.of("seed")).getValue("seed")).isEqualTo(LOCAL);
	}

	@Test
	void nestedPopRetainsAncestorAndConcurrentRowsHaveIndependentSeeds() {
		BindingFrameBindings.Scope outer = new BindingFrameBindings.Scope();
		BindingFrameBindings.Scope inner = new BindingFrameBindings.Scope();
		BindingSet first = BindingFrameBindings.push(outer, EmptyBindingSet.getInstance(), row("seed", VALUE), CONTEXT);
		BindingSet second = BindingFrameBindings.push(outer, EmptyBindingSet.getInstance(), row("seed", LOCAL),
				CONTEXT);
		BindingSet nested = BindingFrameBindings.push(inner, first, row("inner", LOCAL), CONTEXT);
		BindingSet popped = BindingFrameBindings.pop(inner, new QueryBindingSet(nested), CONTEXT);
		assertThat(BindingFrameBindings.probeValue(popped, "inner")).isNull();
		assertThat(BindingFrameBindings.probeValue(popped, "seed")).isEqualTo(VALUE);
		assertThat(CompletableFuture.supplyAsync(() -> BindingFrameBindings.probeValue(first, "seed")).join())
				.isEqualTo(VALUE);
		assertThat(CompletableFuture.supplyAsync(() -> BindingFrameBindings.probeValue(second, "seed")).join())
				.isEqualTo(LOCAL);
		assertThat(BindingFrameBindings.hasFrame(BindingFrameBindings.pop(outer, popped, CONTEXT))).isFalse();
	}

	@Test
	void customBindingRepresentationRetainsGraphAndProbeMetadataInEitherWrapperOrder() {
		QueryEvaluationContext custom = new QueryEvaluationContext.Minimal(null) {
			@Override
			public MutableBindingSet createBindingSet(BindingSet bindings) {
				MapBindingSet copy = new MapBindingSet();
				bindings.forEach(copy::addBinding);
				return copy;
			}
		};
		BindingSet frame = BindingFrameBindings.push(new BindingFrameBindings.Scope(),
				EmptyBindingSet.getInstance(), row("seed", VALUE), custom);
		MutableBindingSet graph = GraphFrameBindings.supply((MutableBindingSet) frame, "graph", LOCAL);
		MutableBindingSet copy = new BindingSetQueryEvaluationContext(custom).createBindingSet(graph);
		assertThat(GraphFrameBindings.isSupplied(copy, "graph")).isTrue();
		assertThat(BindingFrameBindings.probeValue(copy, "seed")).isEqualTo(VALUE);
		MutableBindingSet graphFirst = GraphFrameBindings.supply(new MapBindingSet(), "graph", LOCAL);
		MutableBindingSet probesSecond = BindingFrameBindings.preserve(frame, graphFirst);
		assertThat(GraphFrameBindings.isSupplied(probesSecond, "graph")).isTrue();
		assertThat(BindingFrameBindings.probeValue(probesSecond, "seed")).isEqualTo(VALUE);
	}

