	@Test
	void scopedConditionRestrictsWithheldInputsForExists() {
		QueryBindingSet invocation = row("allowed", VALUE);
		invocation.addBinding("hidden", LOCAL);
		BindingSet withheld = BindingFrameBindings.without(invocation, Set.of("allowed", "hidden"), CONTEXT);
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
		var hidden = strategy.precompile(new Exists(new Filter(new SingletonSet(), new Bound(Var.of("hidden")))),
				CONTEXT);
		var allowed = strategy.precompile(new Exists(new Filter(new SingletonSet(), new Bound(Var.of("allowed")))),
				CONTEXT);
		assertThat(new ScopedQueryValueEvaluationStep(Set.of("allowed"), hidden).evaluate(withheld))
				.isEqualTo(SimpleValueFactory.getInstance().createLiteral(false));
		assertThat(new ScopedQueryValueEvaluationStep(Set.of("allowed"), allowed).evaluate(withheld))
				.isEqualTo(SimpleValueFactory.getInstance().createLiteral(true));
	}

	@Test
	void substitutionDomainSurvivesCopiesProjectionReplayAndSerialization() throws Exception {
		BindingSet outer = BindingFrameBindings.withSubstitutionDomain(row("x", VALUE), Set.of("x", "hidden"),
				CONTEXT);
		BindingFrameBindings.Scope owner = new BindingFrameBindings.Scope();
		BindingSet framed = BindingFrameBindings.push(owner, outer, row("probe", LOCAL), CONTEXT);
		BindingSet isolated = BindingFrameBindings.isolate(framed, CONTEXT);
		BindingSet copy = new QueryBindingSet(isolated);
		assertThat(BindingFrameBindings.substitutionDomain(copy)).containsExactlyInAnyOrder("x", "hidden");
		BindingSet restricted = BindingFrameBindings.retainWithheldInputs(copy, new QueryBindingSet(copy), Set.of("x"));
		assertThat(BindingFrameBindings.substitutionDomain(restricted)).containsExactly("x");
		assertThat(BindingFrameBindings.substitutionDomain(copy)).containsExactlyInAnyOrder("x", "hidden");
		BindingSet nested = BindingFrameBindings.withSubstitutionDomain(restricted, Set.of(), CONTEXT);
		assertThat(BindingFrameBindings.substitutionDomain(nested)).isEmpty();
		try (var rows = BindingFrameReplay.fresh(input -> {
			assertThat(BindingFrameBindings.substitutionDomain(input)).isEmpty();
			return new SingletonIteration<>(input);
		}, nested, DefaultCollectionFactory::new, CONTEXT)) {
			assertThat(BindingFrameBindings.substitutionDomain(rows.next())).isEmpty();
			assertThat(rows.hasNext()).isFalse();
		}
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
			output.writeObject(nested);
		}
		try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			BindingSet restored = (BindingSet) input.readObject();
			assertThat(BindingFrameBindings.substitutionDomain(restored)).isEmpty();
			assertThat(restored.getValue("x")).isEqualTo(VALUE);
			assertThat(BindingFrameBindings.probeValue(restored, "probe")).isNull();
		}
	}

	@Test
	void lateralAuthorityRespectsNearestInvocationAndSerialization() throws Exception {
		BindingSet outer = BindingFrameBindings.withSubstitutionDomain(row("api", VALUE), Set.of("api"), CONTEXT);
		BindingSet lateral = BindingFrameBindings.withLateralDomain(outer, Set.of("api", "x"), Set.of("x"), CONTEXT);
		assertThat(BindingFrameBindings.substitutionDomain(lateral)).containsExactlyInAnyOrder("api", "x");
		assertThat(BindingFrameBindings.lateralPrivateInputs(lateral)).containsExactly("x");
		BindingSet exists = BindingFrameBindings.withSubstitutionDomain(lateral, Set.of(), CONTEXT);
		assertThat(BindingFrameBindings.substitutionDomain(exists)).isEmpty();
		assertThat(BindingFrameBindings.lateralPrivateInputs(exists)).isEmpty();
		BindingSet inner = BindingFrameBindings.withLateralDomain(exists, Set.of("y"), Set.of("y"), CONTEXT);
		assertThat(BindingFrameBindings.substitutionDomain(inner)).containsExactly("y");
		assertThat(BindingFrameBindings.lateralPrivateInputs(inner)).containsExactly("y");

		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
			output.writeObject(inner);
		}
		try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			BindingSet restored = (BindingSet) input.readObject();
			assertThat(BindingFrameBindings.substitutionDomain(restored)).containsExactly("y");
			assertThat(BindingFrameBindings.lateralPrivateInputs(restored)).containsExactly("y");
			BindingSet nextExists = BindingFrameBindings.withSubstitutionDomain(restored, Set.of(), CONTEXT);
			assertThat(BindingFrameBindings.lateralPrivateInputs(nextExists)).isEmpty();
		}
	}

	@Test
	void privateProjectionCannotResurrectWithheldProbesOrGraphProvenance() throws Exception {
		MutableBindingSet supplied = GraphFrameBindings.supply(row("x", VALUE), "graph", LOCAL);
		BindingSet withheld = BindingFrameBindings.without(supplied, Set.of("x"), CONTEXT);
		BindingSet framed = BindingFrameBindings.push(new BindingFrameBindings.Scope(), withheld, row("x", LOCAL),
				CONTEXT);
		BindingSet lateral = BindingFrameBindings.withLateralDomain(framed, Set.of("x", "graph"),
				Set.of("x", "graph"), CONTEXT);
		assertThat(BindingFrameBindings.hideLateralProjectionInputs(lateral, Set.of("x", "graph"), CONTEXT))
				.isSameAs(lateral);
		BindingSet body = BindingFrameBindings.hideLateralProjectionInputs(lateral, Set.of(), CONTEXT);
		assertThat(body.hasBinding("graph")).isFalse();
		assertThat(BindingFrameBindings.probeValue(body, "x")).isNull();
		assertThat(BindingFrameBindings.withheldInput(body, "x")).isNull();
		assertThat(BindingFrameBindings.substitutionDomain(body)).isEmpty();
		assertThat(BindingFrameBindings.lateralPrivateInputs(body)).isEmpty();
		Map<String, Value> retained = new HashMap<>();
		GraphFrameBindings.from(body).visit(retained::put);
		assertThat(retained).isEmpty();
		assertThat(BindingFrameBindings.withheldInput(lateral, "x")).isEqualTo(VALUE);
		assertThat(GraphFrameBindings.isSupplied(lateral, "graph")).isTrue();
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
			output.writeObject(body);
		}
		try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			BindingSet restored = (BindingSet) input.readObject();
			assertThat(BindingFrameBindings.from(restored).projectionRemovalCounts())
					.containsEntry("x", 1)
					.containsEntry("graph", 1);
			assertThat(BindingFrameBindings.withheldInput(restored, "x")).isNull();
		}
	}

